# 99_export_synthetic_csv.R -- write the simulated analysis cohort as a plain CSV
#
# Why this exists. synthetic/README.md says the archival snapshot contains jamda_synthetic.csv,
# so that a reader without R can still inspect the simulated cohort. Version 1.0.0 did not
# actually ship that file. This script produces it from the pipeline output, deterministically,
# so the claim in the README is true and the file can be regenerated byte-for-byte.
#
# Run from the repository root, after 00_make_synthetic_raw.R and 01_build.R:
#   Rscript code/99_export_synthetic_csv.R
#
# The numbers in this file are SIMULATED. They are not CHARLS respondent data and they do not
# reproduce the published estimates.

suppressMessages({library(dplyr)})
stopifnot(file.exists("out/jamda_full.rds"))
m <- readRDS("out/jamda_full.rds")
m <- as.data.frame(m)
m[] <- lapply(m, function(x) if (inherits(x, "haven_labelled")) as.numeric(x) else x)
m <- m[, vapply(m, function(x) !is.list(x), logical(1))]
dir.create("synthetic", showWarnings = FALSE)
out <- "synthetic/jamda_synthetic.csv"
write.csv(m, out, row.names = FALSE, na = "")
cat(sprintf("wrote %s: %d rows x %d columns, %.2f MB\n",
            out, nrow(m), ncol(m), file.size(out)/1024^2))
